/* ============================================================
   Fashion: wearable costumes, hats, face items, back items and
   weapon skins that change the 3D model. All designs original.
   ============================================================ */
const FP = { black: '#1e1a22', white: '#f4f0e7', red: '#c8402a', navy: '#1f2a4a', gold: '#d9a845', pink: '#f0a0c0', brown: '#6b4428', skin: '#ffe1c8', orange: '#e8842a', green: '#4a8a3a', blue: '#3a6ad0', purple: '#6a3aa0', gray: '#8a8a94', steel: '#c9ced8', cream: '#efe3c4', teal: '#2aa0a0', yellow: '#f0d040', dark: '#2a2430', leaf: '#6ab04a', sky: '#8fd3ff', wine: '#7a1a30', khaki: '#b8a070', lime: '#b8e040', mint: '#8ae0c0', cyan: '#40e0ff', silver: '#e0e4ec', wood: '#8a6240', ice: '#bfeaff', lava: '#ff6a2a', coral: '#ff8a70', rose: '#e05080' };
const F = {}; for (const k in FP) F[k] = hc(FP[k]);
const dk = (c, k = .75) => shade(c, k);

/* ---------- geometry helpers ---------- */
const FH = {
  ears(g, col, inner, kind = 'cat') {
    for (const s of [-1, 1]) {
      if (kind === 'cat') { g.cone(s * .3, .72, -.02, s * .35, 1, -.1, .15, .36, 4, col); g.cone(s * .3, .74, .0, s * .3, 1, -.05, .08, .26, 4, inner); }
      else if (kind === 'fox') { g.cone(s * .33, .7, -.04, s * .45, 1, -.15, .17, .5, 4, col); g.cone(s * .33, .72, -.02, s * .4, 1, -.1, .09, .36, 4, inner); }
      else if (kind === 'bunny') { g.ell(s * .2, 1.1, -.05, .11, .42, .07, col, 6, 5, .1, 0); g.ell(s * .2, 1.1, -.0, .06, .3, .04, inner, 5, 4, .1, 0); }
      else if (kind === 'bear') { g.sphere(s * .4, .8, -.05, .17, col, 7, 5); g.sphere(s * .4, .8, .02, .1, inner, 6, 4); }
      else if (kind === 'panda') { g.sphere(s * .4, .82, -.05, .16, F.black, 7, 5); }
      else if (kind === 'mouse') { g.ell(s * .45, .8, -.05, .2, .2, .05, col, 8, 5); g.ell(s * .45, .8, -.0, .13, .13, .04, inner, 7, 4); }
    }
  },
  hood(g, col, col2) { g.jit = .02; g.sphereSkip(0, .44, -.02, .58, col, 16, 12, c => (c[2] > .2 && c[1] < .25) || c[1] < -.4); g.cyl(0, -.05, 0, .56, .6, .1, 14, col2 || dk(col), null, true); g.jit = .03; },
  hat(g, brimR, crownR, h, col, band) { g.cyl(0, 0, 0, brimR, brimR, .05, 16, col, shade(col, 1.08)); g.cyl(0, .04, 0, crownR, crownR * .92, h, 14, col, shade(col, 1.1)); if (band) g.cyl(0, .07, 0, crownR + .02, crownR + .02, .1, 14, band, null, true); },
  ring(g, r, t, col, seg = 12, y = 0) { for (let i = 0; i < seg; i++) { const a = i / seg * TAU, a2 = (i + 1) / seg * TAU; g.push((Math.cos(a) + Math.cos(a2)) / 2 * r, y, (Math.sin(a) + Math.sin(a2)) / 2 * r, 0, -(a + a2) / 2, 0); g.box(0, 0, 0, t, t, r * TAU / seg + t * .4, col); g.pop(); } },
  wing(g, col, col2, n = 4, L = .9, feather = true) { for (let i = 0; i < n; i++) { const rz = .85 - i * (1.2 / n), Ln = L - i * (L * .12); g.at(.1, 0, 0, 0, 1, 1, 1, 0, rz); g.box(Ln / 2 + .05, 0, 0, Ln, .07, .05, dk(col)); g.box(Ln / 2 + .05, -.12, 0, Ln * .92, .22, .03, i % 2 ? col : col2 || col); g.reset(); if (feather) g.cone(.05 + Ln, 0, 0, 1, -.25, 0, .05, .18, 3, col2 || col); } g.sphere(.1, 0, 0, .13, dk(col), 5, 4); },
  tail(g, col, tip, L = .7, r = .07, curl = .3) { for (let i = 0; i < 6; i++) { const t = i / 5; g.sphere(0, -.05 - Math.sin(t * 2.2) * L * .35, -.1 - t * L, r * (1 - t * .3) + (tip && i > 3 ? .03 : 0), i > 3 && tip ? tip : col, 6, 4); } },
  pom(g, x, y, z, r, col) { g.jit = .08; g.sphere(x, y, z, r, col, 7, 5); g.jit = .03; },
  stripe(g, y, r, h, col, n = 6) { for (let i = 0; i < n; i++) { const a = i / n * TAU; g.push(Math.cos(a) * r, y, Math.sin(a) * r, 0, -a, 0); g.box(0, 0, 0, .03, h, .14, col); g.pop(); } },
  glasses(g, lens, frame) { for (const s of [-1, 1]) { g.push(s * .19, .4, .47); g.box(0, 0, 0, .26, .17, .03, frame); g.box(0, 0, .01, .22, .13, .03, lens); g.pop(); } g.box(0, .41, .47, .14, .025, .025, frame); for (const s of [-1, 1]) g.box(s * .42, .42, .2, .025, .025, .5, frame); },
  roundGlasses(g, lens, frame) { for (const s of [-1, 1]) { g.push(s * .19, .4, .47, Math.PI / 2, 0, 0); FH.ring(g, .12, .025, frame, 10, 0); g.cyl(0, -.005, 0, .11, .11, .01, 10, lens, null, true); g.pop(); } g.box(0, .41, .47, .14, .025, .025, frame); for (const s of [-1, 1]) g.box(s * .42, .42, .2, .025, .025, .5, frame); },
  emblem(g, x, y, z, col) { g.box(x, y, z, .12, .12, .02, col); g.box(x, y, z + .005, .06, .18, .015, shade(col, .8)); }
};

